// Normaliza una ruta para buscar en el mapa (sin dominio, sin query/hash, sin barra final).
export function normalizeMetaPath(p) {
  let s = (p || "/").split("?")[0].split("#")[0];
  if (!s.startsWith("/")) s = "/" + s;
  if (s.length > 1 && s.endsWith("/")) s = s.slice(0, -1);
  return s;
}
